      out.write("        for (var i = 0; i < 45; i++) {\n");
      out.write("            var s = document.createElement('div');\n");
      out.write("            s.className = 'vn-star';\n");
      out.write("            var sz = (Math.random() * 2 + 1.2).toFixed(1);\n");
      out.write("            s.style.width = sz + 'px';\n");
      out.write("            s.style.height = sz + 'px';\n");
